mapper.select:
select A.order_id, A.client_uid, A.pet_name, A.pet_weight, A.pet_photo, A.remark, A.start_date, A.duration, A.progress, A.cage_no, A.create_by, A.create_by_name, A.create_time, A.update_by, A.update_by_name, A.update_time, B.username as client_name from foster as A left join user as B on (A.client_uid=B.id)
and A.progress = #{progress}
order by A.order_id desc
